  if exists (
    select 1
    from w4d3_dams_source
    group by source, country_code, source_asset_id
    having count(*) > 1
  ) then
    raise exception 'W4D-3 duplicate dam source identity.';
  end if;

  if exists (
    select 1
    from w4d3_reservoirs_source
    group by source, country_code, source_asset_id
    having count(*) > 1
  ) then
    raise exception 'W4D-3 duplicate reservoir source identity.';
  end if;

  if exists (
    select 1
    from w4d3_relations_source
    group by relation_type, dam_source_asset_id, reservoir_source_asset_id
    having count(*) > 1
  ) then
    raise exception 'W4D-3 duplicate eligible relation identity.';
  end if;

  if exists (
    select 1
    from w4d3_dams_source
    where jsonb_typeof(raw_payload_json::jsonb) <> 'object'
  ) then
    raise exception 'W4D-3 dam raw payload must be a JSON object.';
  end if;

  if exists (
    select 1
    from w4d3_reservoirs_source
    where jsonb_typeof(raw_payload_json::jsonb) <> 'object'
  ) then
    raise exception 'W4D-3 reservoir raw payload must be a JSON object.';
  end if;

  if exists (
    select 1
    from w4d3_relations_source
    where jsonb_typeof(evidence_json::jsonb) <> 'object'
  ) then
    raise exception 'W4D-3 relation evidence must be a JSON object.';
  end if;
end;
$$;

insert into public.dams as target (
  source,
  country_code,
  asset_type,
  source_asset_id,
  source_record_number,
  source_record_fingerprint,
  source_numeric_id,
  register_id,
  name,
  name_en,
  source_river_name,
  resolved_river_name,
  river_resolution_status,
  county,
  basin_code,
  basin_name,
  latitude,
  longitude,
  importance_class,
  importance_category,
  owner,
  reservoir_type,
  dam_type,
  uses,
  cadastre_code,
  match_key,
  canonicalization_status,
  map_eligible,
  raw_payload
)
select
  btrim(source),
  upper(btrim(country_code)),
  btrim(asset_type),
  btrim(source_asset_id),
  btrim(source_record_number)::integer,
  lower(btrim(source_record_fingerprint)),
  btrim(source_numeric_id)::integer,
  btrim(register_id),
  btrim(name),
  nullif(btrim(name_en), ''),
  nullif(btrim(source_river_name), ''),
  nullif(btrim(resolved_river_name), ''),
  btrim(river_resolution_status),
  nullif(btrim(county), ''),
  nullif(btrim(basin_code), ''),
  nullif(btrim(basin_name), ''),
  btrim(latitude)::double precision,
  btrim(longitude)::double precision,
  nullif(btrim(importance_class), ''),
  nullif(btrim(importance_category), ''),
  nullif(btrim(owner), ''),
  nullif(btrim(reservoir_type), ''),
  nullif(btrim(dam_type), ''),
  nullif(btrim(uses), ''),
  nullif(btrim(cadastre_code), ''),
  nullif(btrim(match_key), ''),
  btrim(canonicalization_status),
  case lower(btrim(map_eligible))
    when 'true' then true
    when 'false' then false
    else null
  end,
  raw_payload_json::jsonb
from w4d3_dams_source
on conflict (source, country_code, source_asset_id)
do update set
  source_record_number = excluded.source_record_number,
  source_record_fingerprint = excluded.source_record_fingerprint,
  source_numeric_id = excluded.source_numeric_id,
  register_id = excluded.register_id,
  name = excluded.name,
  name_en = excluded.name_en,
  source_river_name = excluded.source_river_name,
  resolved_river_name = excluded.resolved_river_name,
  river_resolution_status = excluded.river_resolution_status,
  county = excluded.county,
  basin_code = excluded.basin_code,
  basin_name = excluded.basin_name,
  latitude = excluded.latitude,
  longitude = excluded.longitude,
  importance_class = excluded.importance_class,
  importance_category = excluded.importance_category,
  owner = excluded.owner,
  reservoir_type = excluded.reservoir_type,
  dam_type = excluded.dam_type,
  uses = excluded.uses,
  cadastre_code = excluded.cadastre_code,
  match_key = excluded.match_key,
  canonicalization_status = excluded.canonicalization_status,
  map_eligible = excluded.map_eligible,
  raw_payload = excluded.raw_payload
where (
  to_jsonb(target)
    - array['id', 'created_at', 'updated_at', 'water_body_id']
) is distinct from (
  to_jsonb(excluded)
    - array['id', 'created_at', 'updated_at', 'water_body_id']
);

