do $$
declare
  unresolved_count bigint;
  duplicate_pair_count bigint;
begin
  select count(*)
    into unresolved_count
  from w4d3_relations_source as relation_source
  left join public.dams as dam
    on dam.source = 'ANAR'
    and dam.country_code = 'RO'
    and dam.source_asset_id = btrim(relation_source.dam_source_asset_id)
  left join public.reservoirs as reservoir
    on reservoir.source = 'ANAR'
    and reservoir.country_code = 'RO'
    and reservoir.source_asset_id =
      btrim(relation_source.reservoir_source_asset_id)
  where dam.id is null
    or reservoir.id is null;

  if unresolved_count <> 0 then
    raise exception
      'W4D-3 has % unresolved eligible relations.',
      unresolved_count;
  end if;

  select count(*)
    into duplicate_pair_count
  from (
    select
      btrim(relation_source.relation_type),
      dam.id,
      reservoir.id
    from w4d3_relations_source as relation_source
    join public.dams as dam
      on dam.source = 'ANAR'
      and dam.country_code = 'RO'
      and dam.source_asset_id = btrim(relation_source.dam_source_asset_id)
    join public.reservoirs as reservoir
      on reservoir.source = 'ANAR'
      and reservoir.country_code = 'RO'
      and reservoir.source_asset_id =
        btrim(relation_source.reservoir_source_asset_id)
    group by
      btrim(relation_source.relation_type),
      dam.id,
      reservoir.id
    having count(*) > 1
  ) as duplicates;

  if duplicate_pair_count <> 0 then
    raise exception
      'W4D-3 resolves to % duplicate canonical relation pairs.',
      duplicate_pair_count;
  end if;
end;
$$;

insert into public.dam_reservoir_relations as target (
  relation_type,
  dam_id,
  reservoir_id,
  relation_origin,
  match_method,
  confidence,
  proposal_status,
  review_status,
  review_reason,
  distance_km,
  map_eligible,
  source,
  evidence
)
select
  btrim(relation_source.relation_type),
  dam.id,
  reservoir.id,
  btrim(relation_source.relation_origin),
  btrim(relation_source.match_method),
  btrim(relation_source.confidence),
  btrim(relation_source.proposal_status),
  btrim(relation_source.review_status),
  nullif(btrim(relation_source.review_reason), ''),
  nullif(btrim(relation_source.distance_km), '')::numeric,
  case lower(btrim(relation_source.map_eligible))
    when 'true' then true
    when 'false' then false
    else null
  end,
  btrim(relation_source.source),
  relation_source.evidence_json::jsonb
from w4d3_relations_source as relation_source
join public.dams as dam
  on dam.source = 'ANAR'
  and dam.country_code = 'RO'
  and dam.source_asset_id = btrim(relation_source.dam_source_asset_id)
join public.reservoirs as reservoir
  on reservoir.source = 'ANAR'
  and reservoir.country_code = 'RO'
  and reservoir.source_asset_id =
    btrim(relation_source.reservoir_source_asset_id)
on conflict (relation_type, dam_id, reservoir_id)
do update set
  relation_origin = excluded.relation_origin,
  match_method = excluded.match_method,
  confidence = excluded.confidence,
  proposal_status = excluded.proposal_status,
  review_status = excluded.review_status,
  review_reason = excluded.review_reason,
  distance_km = excluded.distance_km,
  map_eligible = excluded.map_eligible,
  source = excluded.source,
  evidence = excluded.evidence
where (
  to_jsonb(target) - array['id', 'created_at', 'updated_at']
) is distinct from (
  to_jsonb(excluded) - array['id', 'created_at', 'updated_at']
);

do $$
declare
  baseline record;
  imported_dams bigint;
  imported_reservoirs bigint;
  imported_relations bigint;
  public_dams bigint;
  public_reservoirs bigint;
  public_relations bigint;
begin
  select *
    into baseline
  from w4d3_runtime_baseline;

  if (select count(*) from public.stations) <> baseline.station_count then
    raise exception 'W4D-3 changed public.stations.';
  end if;

  if (
    select count(*)
    from public.daily_water_snapshots
  ) <> baseline.snapshot_count then
    raise exception 'W4D-3 changed public.daily_water_snapshots.';
  end if;

  if (
    select count(distinct station_id)
    from public.daily_water_snapshots
  ) <> baseline.snapshot_station_count then
    raise exception 'W4D-3 changed snapshot station identity.';
  end if;

  select count(*)
    into imported_dams
  from public.dams
  where source = 'ANAR'
    and country_code = 'RO';

  select count(*)
    into imported_reservoirs
  from public.reservoirs
  where source = 'ANAR'
    and country_code = 'RO';

  select count(*)
    into imported_relations
  from public.dam_reservoir_relations as relation
  join public.dams as dam on dam.id = relation.dam_id
  join public.reservoirs as reservoir on reservoir.id = relation.reservoir_id
  where relation.source in ('ANAR', 'ANAR_W3_AUDIT')
    and dam.source = 'ANAR'
    and dam.country_code = 'RO'
    and reservoir.source = 'ANAR'
    and reservoir.country_code = 'RO';

  if imported_dams <> 2202 then
    raise exception
      'W4D-3 expected 2202 imported dams, found %',
      imported_dams;
  end if;

  if imported_reservoirs <> 1933 then
    raise exception
      'W4D-3 expected 1933 imported reservoirs, found %',
      imported_reservoirs;
  end if;

  if imported_relations <> 1090 then
    raise exception
      'W4D-3 expected 1090 imported relations, found %',
      imported_relations;
  end if;

  if (
    select count(*)
    from public.dam_reservoir_relations
    where source = 'ANAR_W3_AUDIT'
  ) <> 926 then
    raise exception
      'W4D-3 expected 926 audit-qualified relations.';
  end if;

  if (
    select count(*)
    from public.dam_reservoir_relations
    where source = 'ANAR'
  ) <> 164 then
    raise exception
      'W4D-3 expected 164 ANAR-provenance relations.';
  end if;

  select count(*)
    into public_dams
  from public.water_dams_public
  where country_code = 'RO';

  select count(*)
    into public_reservoirs
  from public.water_reservoirs_public
  where country_code = 'RO';

  select count(*)
    into public_relations
  from public.dam_reservoir_relations_public;

  if public_dams <> 2200 then
    raise exception
      'W4D-3 expected 2200 map-eligible public dams, found %',
      public_dams;
  end if;

  if public_reservoirs <> 1933 then
    raise exception
      'W4D-3 expected 1933 map-eligible public reservoirs, found %',
      public_reservoirs;
  end if;

  if public_relations <> 1090 then
    raise exception
      'W4D-3 expected 1090 public relations, found %',
      public_relations;
  end if;

  if exists (
    select 1
    from public.reservoirs
    where source = 'ANAR'
      and country_code = 'RO'
      and hydropower_use not in ('H')
      and hydropower_use is not null
  ) then
    raise exception 'W4D-3 altered ANAR hydropower codes.';
  end if;

  if exists (
    select 1
    from public.reservoirs
    where source = 'ANAR'
      and country_code = 'RO'
      and upper(fishery_use) not in ('P')
      and fishery_use is not null
  ) then
    raise exception 'W4D-3 altered ANAR fishery codes.';
  end if;

  if (
    select count(*)
    from public.reservoirs
    where source = 'ANAR'
      and country_code = 'RO'
      and fishery_use = 'P'
  ) <> 1310 then
    raise exception 'W4D-3 expected 1310 uppercase P fishery codes.';
  end if;

  if (
    select count(*)
    from public.reservoirs
    where source = 'ANAR'
      and country_code = 'RO'
      and fishery_use = 'p'
  ) <> 4 then
    raise exception 'W4D-3 expected 4 lowercase p fishery codes.';
  end if;

  if exists (
    select 1
    from public.reservoirs
    where source = 'ANAR'
      and country_code = 'RO'
      and water_supply_use not in ('A')
      and water_supply_use is not null
  ) then
    raise exception 'W4D-3 altered ANAR water-supply codes.';
  end if;

  if exists (
    select 1
    from public.reservoirs
    where source = 'ANAR'
      and country_code = 'RO'
      and recreation_use not in ('R')
      and recreation_use is not null
  ) then
    raise exception 'W4D-3 altered ANAR recreation codes.';
  end if;
end;
$$;

comment on table public.dams is
  'Canonical dam catalog. Romania W4D-3 imported 2202 audited ANAR rows.';

comment on table public.reservoirs is
  'Canonical reservoir catalog. Romania W4D-3 imported 1933 audited ANAR rows.';

comment on table public.dam_reservoir_relations is
  'Canonical dam-reservoir relations. Romania W4D-3 imported 1090 eligible audited relations.';

commit;
